<script setup>import { computed,ref } from 'vue'; import PageHero from '../components/PageHero.vue'; import { relics } from '../data/relics'; import { people } from '../data/people'; import { news } from '../data/news'; import { historyEvents } from '../data/museum'; import { images } from '../data/imageAssets'; const term=ref('');const all=[...relics.map(item=>({...item,type:'文物',to:`/relic/${item.id}`,text:item.summary})),...people.map(item=>({...item,type:'人物',to:`/person/${item.id}`,title:item.name,text:item.summary})),...news.map(item=>({...item,type:'新闻',to:`/news/${item.id}`,text:item.summary})),...historyEvents.map(item=>({...item,type:'历史事件',to:'/history',text:item.description}))];const results=computed(()=>term.value.trim()?all.filter(item=>`${item.title||item.name}${item.text}`.includes(term.value.trim())):[])</script>
<template><PageHero title="全站搜索" description="搜索新闻、文物、历史人物与历史事件的模拟数据。" :image="images.historyPaper" /><section class="section"><div class="shell"><div class="search-box"><input v-model="term" placeholder="输入关键词，例如“演示”" autofocus /><button>搜索</button></div><div v-if="term && results.length" class="search-results"><RouterLink v-for="item in results" :key="`${item.type}-${item.id}`" :to="item.to"><span class="tag">{{ item.type }}</span><h3>{{ item.title || item.name }}</h3><p>{{ item.text }}</p></RouterLink></div><div v-else class="empty-state">{{ term ? '未找到相关演示内容。' : '输入关键词，开始检索。' }}</div></div></section></template>
<style scoped>.search-results{display:grid;gap:14px;max-width:820px;margin:auto}.search-results>a{display:block;background:#fff;border:1px solid var(--line);padding:20px}.search-results h3{margin:0 0 8px}.search-results p{margin:0;color:var(--muted);line-height:1.7}</style>
